/**
 * @param {string} start
 * @param {string} end
 * @param {number} step
 * @yields {string}
 */
var dateRangeGenerator = function* (start, end, step) {
    const DAY_MS = 24 * 60 * 60 * 1000;
    let current = new Date(start).getTime();   // "YYYY-MM-DD" parses as UTC midnight
    const last = new Date(end).getTime();

    while (current <= last) {
        // "YYYY-MM-DDTHH:mm:ss.sssZ" -> keep only the date part
        yield new Date(current).toISOString().slice(0, 10);
        current += step * DAY_MS;              // advance by `step` days
    }
};

